        en: { name: 'La Marmita', description: 'A cosy little restaurant with modern Patagonian cooking: king crab, seafood and lamb in clay pots. It’s known for having only a few tables.', tip: 'Try the crab cream soup and the lamb in a clay pot; arrive before 7:30 pm or book ahead. Cards accepted.' },
        es: { name: 'La Marmita', description: 'Un pequeño y acogedor restaurante de cocina patagónica moderna: centolla, mariscos y cordero en cazuelas de barro. Es conocido por tener solo unas pocas mesas.', tip: 'Prueba la crema de centolla y el cordero en cazuela; llega antes de las 19:30 o reserva con antelación. Aceptan tarjeta.' },
        de: { name: 'La Marmita', description: 'Ein gemütliches kleines Restaurant mit moderner patagonischer Küche: Königskrabbe, Meeresfrüchte und Lamm im Tontopf. Bekannt ist es dafür, dass es nur wenige Tische hat.', tip: 'Probier die Krabbencremesuppe und das Lamm im Tontopf; komm vor 19:30 Uhr oder reserviere vorab. Kartenzahlung ist möglich.' },
        fr: { name: 'La Marmita', description: 'Un petit restaurant chaleureux à la cuisine patagonne moderne : centolla (crabe royal), fruits de mer et agneau en cocotte. Il est connu pour ne compter que quelques tables.', tip: 'Goûtez la crème de crabe et l’agneau en cocotte ; arrivez avant 19 h 30 ou réservez. Cartes acceptées.' },
        it: { name: 'La Marmita', description: 'Un piccolo ristorante accogliente con cucina patagonica moderna: granchio reale, frutti di mare e agnello in terracotta. È noto per avere solo pochi tavoli.', tip: 'Assaggia la crema di granchio e l’agnello in terracotta; arriva prima delle 19:30 o prenota. Si paga con carta.' },
